import Foundation

/// Describes the input selected for dispatch, not whether its UI effect succeeded.
/// Keep this separate from model-written labels: "Inspecting the page" could mean
/// a real shortcut, a click, or another screenshot that sends no input at all.
public enum ActionDispatchSummary {
    public static func batch(_ actions: [ComputerAction]) -> String {
        guard !actions.isEmpty else { return "no actions" }
        return actions.map(summary).joined(separator: " → ")
    }

    /// Native IDs are generated by the reader. Labels, field values, and help text
    /// are deliberately absent, including when a malformed diagnostic is supplied.
    public static func native(action: String, element: AccessibilityElement) -> String {
        let operation = nativeActions.contains(action) ? action : "unsupported AX action"
        let suffix = element.id.dropFirst()
        let isGeneratedID = element.id.hasPrefix("e") && !suffix.isEmpty
            && suffix.count <= 12 && suffix.allSatisfy { $0.isASCII && $0.isNumber }
        let target = isGeneratedID ? element.id : "<target>"
        let role = nativeRoles.contains(element.role) ? element.role : "AXControl"
        return "\(operation) \(target) \(role)"
    }

    private static func summary(_ action: ComputerAction) -> String {
        switch action.type.lowercased() {
        case "click", "double_click":
            let button = action.button?.lowercased() ?? "left"
            let name = mouseButtons.contains(button) ? button : "<button>"
            return "\(action.type.lowercased()) \(name) \(point(x: action.x, y: action.y))\(modifiers(action.keys))"
        case "move":
            return "move \(point(x: action.x, y: action.y))\(modifiers(action.keys))"
        case "scroll":
            return "scroll Δ(\(number(action.scrollX)), \(number(action.scrollY))) at \(point(x: action.x, y: action.y))\(modifiers(action.keys))"
        case "drag":
            let points = action.path ?? []
            return "drag \(points.count) points \(point(x: points.first?.x, y: points.first?.y)) to \(point(x: points.last?.x, y: points.last?.y))\(modifiers(action.keys))"
        case "type":
            // Counting user-visible characters avoids retaining the actual typed
            // content in diagnostics, even for multiline text or emoji.
            return "type \(action.text?.count ?? 0) characters"
        case "keypress": return "keypress \(shortcut(action.keys ?? []))"
        case "wait": return "wait (no input)"
        case "screenshot": return "screenshot (no input)"
        default: return "unsupported action"
        }
    }

    private static func point(x: Double?, y: Double?) -> String {
        "(\(number(x)), \(number(y)))"
    }

    private static func number(_ value: Double?) -> String {
        guard let value, value.isFinite, abs(value) <= 10_000_000 else { return "?" }
        return String(format: value.rounded() == value ? "%.0f" : "%.1f",
                      locale: Locale(identifier: "en_US_POSIX"), value)
    }

    private static func modifiers(_ keys: [String]?) -> String {
        let names = (keys ?? []).compactMap { modifierNames[normalized($0)] }
        return names.isEmpty ? "" : " + " + names.joined(separator: "+")
    }

    private static func shortcut(_ keys: [String]) -> String {
        guard !keys.isEmpty, keys.count <= 5 else { return "<invalid shortcut>" }
        let normalizedKeys = keys.map(normalized)
        let isCommandShortcut = normalizedKeys.contains { ["CMD", "CTRL"].contains(modifierNames[$0] ?? "") }
        return normalizedKeys.map { key in
            if let modifier = modifierNames[key] { return modifier }
            if let name = specialKeys[key] { return name }
            if functionKeys.contains(key) { return key.uppercased() }
            // Command/Control plus an ASCII key names a shortcut. A bare printable
            // key, or Shift/Option typing, can reveal user text and stays redacted.
            if key.count == 1 {
                if isCommandShortcut, let scalar = key.unicodeScalars.first,
                   (33...126).contains(scalar.value) { return key.uppercased() }
                return "<character>"
            }
            return "<key>"
        }.joined(separator: "+")
    }

    private static func normalized(_ key: String) -> String {
        key == " " ? "space" : key.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
    }

    private static let mouseButtons: Set<String> = ["left", "right", "middle", "back", "forward"]
    private static let nativeActions: Set<String> = ["AXPress", "AXShowMenu", "AXIncrement", "AXDecrement"]
    private static let nativeRoles: Set<String> = [
        "AXButton", "AXLink", "AXMenuBar", "AXMenuBarItem", "AXMenu", "AXMenuItem", "AXGroup",
        "AXStaticText", "AXCheckBox", "AXRadioButton", "AXSlider", "AXIncrementor", "AXPopUpButton",
        "AXTextField", "AXTextArea", "AXComboBox", "AXTabGroup", "AXToolbar", "AXRow", "AXCell",
        "AXImage", "AXWindow", "AXScrollBar", "AXScrollArea", "AXSplitGroup", "AXDisclosureTriangle"
    ]
    private static let modifierNames = [
        "cmd": "CMD", "command": "CMD", "meta": "CMD", "super": "CMD",
        "ctrl": "CTRL", "control": "CTRL", "alt": "ALT", "option": "ALT", "shift": "SHIFT"
    ]
    private static let specialKeys = [
        "enter": "ENTER", "return": "ENTER", "tab": "TAB", "space": "SPACE", "spacebar": "SPACE",
        "backspace": "BACKSPACE", "delete": "DELETE", "del": "DELETE", "forwarddelete": "DELETE",
        "esc": "ESC", "escape": "ESC", "home": "HOME", "end": "END", "pageup": "PAGEUP", "pagedown": "PAGEDOWN",
        "left": "LEFT", "arrowleft": "LEFT", "right": "RIGHT", "arrowright": "RIGHT",
        "down": "DOWN", "arrowdown": "DOWN", "up": "UP", "arrowup": "UP"
    ]
    private static let functionKeys = Set((1...20).map { "f\($0)" })
}
